.sl-gallery-filmstrip { padding-block: clamp(3rem, 6vw, 4.5rem); background-color: var(--smartlearn-bg); font-family: var(--smartlearn-body-font, system-ui, sans-serif); overflow-x: clip; }
.sl-gallery-filmstrip .sl-container { max-width: 1200px; width: 100%; margin-inline: auto; padding-inline: clamp(1rem, 3vw, 2rem); }
.sl-gallery-filmstrip .sl-filmstrip-header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-end; gap: 1rem; margin-bottom: 2rem; }
.sl-gallery-filmstrip .sl-section-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.75rem, 3.5vw, 2.25rem); font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.5rem; }
.sl-gallery-filmstrip .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0; }
.sl-gallery-filmstrip .sl-filmstrip-controls { display: flex; gap: 0.625rem; }
.sl-gallery-filmstrip .sl-fs-nav { width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.35)); background-color: var(--smartlearn-card-bg); color: var(--smartlearn-text); display: inline-flex; align-items: center; justify-content: center; cursor: pointer; }
.sl-gallery-filmstrip .sl-fs-nav:hover { border-color: var(--smartlearn-primary); color: var(--smartlearn-primary); }
.sl-gallery-filmstrip .sl-fs-nav:focus-visible, .sl-gallery-filmstrip .sl-filmstrip-scroll-container:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
[dir="rtl"] .sl-gallery-filmstrip .sl-fs-nav svg { transform: scaleX(-1); }
.sl-gallery-filmstrip .sl-filmstrip-scroll-container { display: flex; gap: 1.5rem; padding: 0.75rem clamp(1rem, 3vw, 2rem) 2rem; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: thin; }
.sl-gallery-filmstrip .sl-filmstrip-item { flex: 0 0 85%; max-width: 460px; scroll-snap-align: center; display: flex; flex-direction: column; gap: 0.875rem; transition: transform 0.25s ease; }
.sl-gallery-filmstrip .sl-filmstrip-media { position: relative; width: 100%; aspect-ratio: 4/3; border-radius: var(--smartlearn-radius, 1rem); overflow: hidden; background-color: var(--smartlearn-card-bg); box-shadow: 0 10px 20px rgba(0, 0, 0, 0.08); }
.sl-gallery-filmstrip .sl-filmstrip-media img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-gallery-filmstrip .sl-play-overlay { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 64px; height: 64px; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); border: none; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25); cursor: pointer; transition: transform 0.2s ease, background-color 0.2s ease; z-index: 5; }
.sl-gallery-filmstrip .sl-play-overlay:hover { background: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); transform: translate(-50%, -50%) scale(1.08); }
.sl-gallery-filmstrip .sl-play-overlay:focus-visible, .sl-gallery-filmstrip .sl-close-video:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-gallery-filmstrip .sl-close-video { position: absolute; top: 0.75rem; inset-inline-end: 0.75rem; z-index: 20; width: 44px; height: 44px; border-radius: 50%; border: none; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-size: 1.35rem; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.sl-gallery-filmstrip .sl-filmstrip-caption { font-size: 1.1rem; font-weight: 600; color: var(--smartlearn-text); padding-inline: 0.25rem; }
.sl-gallery-filmstrip .sl-item-quote { justify-content: center; background-color: var(--smartlearn-card-bg); border-radius: var(--smartlearn-radius, 1rem); padding: clamp(1.5rem, 3vw, 2.5rem); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); aspect-ratio: auto; min-height: 220px; box-shadow: 0 10px 20px rgba(0, 0, 0, 0.06); }
.sl-gallery-filmstrip .sl-quote-icon { margin-bottom: 1rem; }
.sl-gallery-filmstrip .sl-quote-text { font-size: clamp(1.15rem, 2.5vw, 1.4rem); font-weight: 600; color: var(--smartlearn-text); line-height: 1.45; margin: 0 0 1.25rem; font-style: italic; }
.sl-gallery-filmstrip .sl-quote-author { display: block; font-style: normal; font-size: 0.95rem; color: var(--smartlearn-text-muted); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; }
@media (min-width: 768px) { .sl-gallery-filmstrip .sl-filmstrip-scroll-container { padding-inline: 5vw; gap: 2rem; } .sl-gallery-filmstrip .sl-filmstrip-item { flex: 0 0 400px; } .sl-gallery-filmstrip .sl-item-quote { aspect-ratio: 4/3; } }
@media (prefers-reduced-motion: no-preference) { .sl-gallery-filmstrip .sl-filmstrip-item:hover { transform: translateY(-5px); } }
@media (prefers-reduced-motion: reduce) { .sl-gallery-filmstrip .sl-filmstrip-item, .sl-gallery-filmstrip .sl-play-overlay { transition: none; } }

